guided.solution:
def choose_visual(q):
    k = q["kind"]
    if k == "single":
        return "card"
    if k == "trend":
        return "line"
    if k == "relationship":
        return "scatter"
    if k == "detail":
        return "table"
    n = q["categories"]
    if k == "part":
        return "donut" if n <= 5 else "bar"
    return "column" if n <= 7 else "bar"

for q in [{"kind": "part", "categories": 4}, {"kind": "part", "categories": 9}, {"kind": "compare", "categories": 8}]:
    print(choose_visual(q))
